let songs=[],category='All songs',query='',favs=[];try{favs=JSON.parse(localStorage.getItem('lucas-song-favourites')||'[]');if(!Array.isArray(favs))favs=[]}catch{}const $=s=>document.querySelector(s);const categories=['All songs','Vehicles','Move & explore','Animals & nature','Everyday words','Rhythm & rhyme','Stories & adventure','Words & numbers','Science & world','Music & singing','♥ Favourites'];function render(){ $('#filters').innerHTML=categories.map(c=>`<button aria-pressed="${c===category}" data-category="${c}">${c}</button>`).join('');let age=$('#age').value;let shown=songs.filter(s=>(age==='all'||(age==='little'&&s.collection==='little')||(age==='4–5'&&s.collection==='explorers'&&['4–5','4–8'].includes(s.ageRange))||(age==='6–8'&&s.collection==='explorers'&&['6–8','4–8'].includes(s.ageRange)))&&(category==='All songs'||category===s.category||(category==='♥ Favourites'&&favs.includes(s.id)))&&[s.title,s.artist,s.words,s.why].join(' ').toLowerCase().includes(query));$('#count').textContent=`${shown.length} songs to explore`;$('#grid').innerHTML=shown.map(s=>`<article class="card"><div class="emoji" aria-hidden="true">${s.emoji}</div><span class="badge">${s.badge} · roughly ${s.ageRange}</span><h3>${s.title}</h3><p class="artist">${s.artist}</p><p class="why">${s.why}</p><p class="words">Try these words: ${s.words}</p><div class="cardbottom"><button class="open" data-song="${s.id}">Sing & play ↗</button><button class="fav" data-fav="${s.id}" aria-label="${favs.includes(s.id)?'Remove':'Save'} ${s.title} ${favs.includes(s.id)?'from':'to'} favourites" aria-pressed="${favs.includes(s.id)}">${favs.includes(s.id)?'♥':'♡'}</button></div></article>`).join('')||'<p>No songs here yet. Try another category or save a favourite with the heart.</p>'}function openSong(id){let s=songs.find(s=>s.id===id);if(!s)return;$('#detailbody').innerHTML=`<div class="emoji">${s.emoji}</div><p class="eyebrow">${s.category}</p><h2>${s.title}</h2><p class="artist">${s.artist}</p><p><b>Suggested starting range: ${s.ageRange}</b> · Follow interest and familiarity, not a timetable.</p><p>${s.why}</p><p><b>Words to play with</b><br>${s.words}</p><p><b>Try it together</b><br>${s.play}</p><a class="watch" href="${s.url}" target="_blank" rel="noopener">Open song ↗</a><a class="source" href="${s.source}" target="_blank" rel="noopener">Official source & song information ↗</a>`;$('#detail').showModal()}document.addEventListener('click',e=>{let c=e.target.closest('[data-category]'),s=e.target.closest('[data-song]'),f=e.target.closest('[data-fav]');if(c){category=c.dataset.category;render()}if(s)openSong(s.dataset.song);if(f){let id=f.dataset.fav;favs=favs.includes(id)?favs.filter(x=>x!==id):[...favs,id];try{localStorage.setItem('lucas-song-favourites',JSON.stringify(favs))}catch{}render()}});$('#age').addEventListener('change',render);$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();render()});$('#close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});fetch('songs.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{songs=data;render()}).catch(()=>{$('#count').textContent='The song shelf could not load. Please reload when connected.'});
